tool_input.content:
const base = process.argv[2];
const { handle } = await import(`${base}/src/api.js`);
const { tick } = await import(`${base}/src/scheduler.js`);

const create = (tz, at) =>
  handle({ method: 'POST', path: '/reminders', body: { userId: 'u' + tz, text: 't', at, tzOffsetMin: tz } }).body;

const ist = create(330, '2026-03-01T09:00'); // intended 03:30Z
const ny = create(-300, '2026-03-01T09:00'); // intended 14:00Z
console.log('IST due_ms', new Date(ist.due_ms).toISOString(), ' NY due_ms', new Date(ny.due_ms).toISOString());

for (const t of ['2026-02-28T22:00:00Z', '2026-03-01T03:30:00Z', '2026-03-01T14:00:00Z', '2026-03-01T19:00:00Z']) {
  const lines = [];
  await tick(Date.parse(t), { formatter: 'legacy', out: (l) => lines.push(l) });
  console.log(t, '->', JSON.stringify(lines));
}

const bad = handle({ method: 'POST', path: '/reminders', body: { userId: 'x', text: 't', at: '2026-03-01T09:00:00' } });
console.log('at with seconds -> status', bad.status, 'due_ms', bad.body.due_ms);
